# Analyze each changed pair to find minimal edits
import difflib

changed = [(0, 'bhcd', 'bhckabf'), (2, 'ujcagc', 'fxjcic'), (3, 'zwj', 'hwj'), (4, 'ua', 'fxabf')]

for idx, inp, outp in changed:
    print(f"\nAnalyzing pair {idx}: '{inp}' -> '{outp}'")

    # Find differences using difflib
    matcher = difflib.SequenceMatcher(None, inp, outp)
    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag != 'equal':
            print(f"  {tag}: '{inp[i1:i2]}' -> '{outp[j1:j2]}' (positions {i1}:{i2} -> {j1}:{j2})")

